!function(){"use strict";window.addEventListener("load",()=>{!function(){const e=document.querySelector(".hamburger-button");if(!e)return;const t=e.querySelector(".hamburger"),r=document.querySelector(".header__slider");e.addEventListener("click",()=>{document.body.classList.toggle("unscrollable"),t.classList.toggle("active"),r.classList.toggle("header__slider--active")})}()})}();
